record('P46',[claim('P46','higgs','SectionII.A(iii) Eqs.(14)-(15)','charged complex scalar S','Pre-breaking Higgs realization is SM plus hidden U1 and one charged complex SM-singlet S; charge conjugation Xprime -> -Xprime,S -> S* stabilizes the vector. No other hidden charged fields in this example. Its single nonzero charge magnitude is removable by the chosen local-algebra generator unit: choose S positive and qS=1. This is an explicit atlas coordinate choice, NOT a printed source numeric charge or global-form assertion.',basis='source_statement_and_single_charge_generator_unit_derivation'),claim('P46','stueck','SectionII.A Eqs.(3)-(10)','δφ = −µǫ','Stueckelberg phi transforms by an affine shift, not a finite-dimensional linear charge irrep. Two examples give field-dependent masses through SM Higgs or hidden real S; S cannot stand in for the eaten shift field. Do not encode the axion as a neutral ordinary scalar and call inventory complete.'),claim('P46','eft','SectionIII Eq.(18) and text below','agnostic attitude to the origin','Phenomenological Eq18 takes the massive real vector X, its Z2 and Higgs portal as an EFT, explicitly agnostic to mass origin. Under the SM-only symmetry of this effective description, X is real singlet Lorentz vector; this is separate from the pre-breaking U1 connection in the Higgs realization.')],
 'All SectionII.A mass-origin examples and explicit SectionIII origin-agnostic EFT.',candidates=[candidate('abelian-higgs',ah,'vector-portal-abelian-higgs',['higgs','baseline']),candidate('vector-eft',veft,'vector-higgs-portal-z2-eft',['eft','baseline'])],models=[{'target_entry_ids':['vector-portal-stueckelberg-scalar','vector-portal-stueckelberg-higgs'],'status':'partial','value_status':'affine_gauge_shift_not_supported_by_linear_irrep_schema','reason':'Shift representation must remain source-backed partial; cannot replace it by a neutral scalar irrep. Higher-dimensional operators and validity cutoff are not additional matter.'}])

